/*
  Execution materials for the 29 test cases: 3275 material uses (1. Case 20044587: 103, 10. Case 27505812: 42, 11. Case 29366372: 83, 12. Case 22251969: 40, 14. Case 24244087: 40, 16. Case 26228185: 58, 18. Case 29802992: 30, 19. Case 22413744: 5, 2. Case 20297618: 87, 20. Case 22995465: 14, 21. Case 23473524: 208, 22. Case 23488445: 20, 23. Case 23819016: 26, 24. Case 23831430: 519, 25. Case 24181354: 418, 26. Case 27617929: 219, 27. Case 28662225: 267, 28. Case 29279905: 61, 29. Case 29974575: 286, 3. Case 20626031: 116, 4. Case 21255400: 153, 5. Case 22342963: 135, 6. Case 22580999: 55, 7. Case 24490144: 77, 8. Case 25926192: 109, 9. Case 27089790: 104).
  Generated by models/hospital/materials_to_sql.py (rules in its docstring). Run after assignments.sql, substeps.sql
  and inventory/item_types.sql.
  Each row is one use: the assignment (the spec, the person's job node, the person), the substep that takes the material
  (NodeId), the inventory type and subtype, the amount in the type's quantifier (Value), when it was recorded (CreationDate).
  Replaces the test cases' earlier material uses (@Reset = 1). If an assignment, substep, type or subtype can't be found,
  the script lists them and writes nothing. Set @Commit = 0 for a dry run.
*/
USE [3b30813b-994f-4bb1-a70f-9763e2b61154];
SET NOCOUNT ON;
SET XACT_ABORT ON;

DECLARE @Commit             bit              = 1;     -- 0 = dry run
DECLARE @Reset              bit              = 1;     -- 1 = replace the test cases' earlier material uses
DECLARE @OrganisationId     uniqueidentifier = 'DA8BA77A-AE36-43E0-A340-278B76345161';
DECLARE @AuthOrganisationId int              = 12;
DECLARE @InvOrganisationId  uniqueidentifier = 'DA8BA77A-AE36-43E0-A340-278B76345161';
DECLARE @ResultId           int              = 45;
DECLARE @CreatedBy          uniqueidentifier = 'A01AE24F-0301-4198-9036-8CC58F070B01';

DECLARE @rows TABLE (SpecName nvarchar(400), TeamName nvarchar(200), JobName nvarchar(200), ExecutorEmail nvarchar(256),
                     SubJob nvarchar(200), SubTeam nvarchar(200), StepIndex int, SubIndex int,
                     TypeName nvarchar(200), SubTypeName nvarchar(200) NULL, Value decimal(18, 3) NULL, CreationDate datetime2,
                     SpecId uniqueidentifier NULL, NodeId int NULL, ExecutorGuid uniqueidentifier NULL, ExecutorInt int NULL,
                     SubstepNodeId int NULL, TypeId int NULL, TypeGuid uniqueidentifier NULL,
                     SubTypeId int NULL, SubTypeGuid uniqueidentifier NULL);

-- The spec, the assignment's job node and executor.
UPDATE r SET SpecId = s.Id FROM @rows r
JOIN [Results].dbo.Specs s ON s.Name COLLATE DATABASE_DEFAULT = r.SpecName COLLATE DATABASE_DEFAULT
                         AND s.ResultId = @ResultId AND s.OrganisationId = @OrganisationId;
DECLARE @jobNodes TABLE (Job nvarchar(200), Team nvarchar(200), NodeId int);
SELECT j.Job, j.Team, MIN(jn.Id)
FROM (SELECT JobName AS Job, TeamName AS Team FROM @rows UNION SELECT SubJob, SubTeam FROM @rows) j
JOIN [Authorisation].dbo.SkillSets tk ON tk.Name COLLATE DATABASE_DEFAULT = j.Team COLLATE DATABASE_DEFAULT
                                     AND tk.NetworkId = 1 AND tk.OrganisationId = @AuthOrganisationId
JOIN dbo.Nodes tn ON tn.SkillSetId = tk.Guid AND tn.NetworkId = 1 AND tn.OrganisationId = @OrganisationId
JOIN [Authorisation].dbo.SkillSets jk ON jk.Name COLLATE DATABASE_DEFAULT = j.Job COLLATE DATABASE_DEFAULT
                                     AND jk.NetworkId = 2 AND jk.OrganisationId = @AuthOrganisationId
JOIN dbo.Nodes jn ON jn.SkillSetId = jk.Guid AND jn.NetworkId = 2 AND jn.ParentNodeId = tn.Id AND jn.OrganisationId = @OrganisationId
GROUP BY j.Job, j.Team;
UPDATE r SET NodeId = j.NodeId FROM @rows r JOIN @jobNodes j ON j.Job = r.JobName AND j.Team = r.TeamName;
UPDATE r SET ExecutorGuid = u.Guid, ExecutorInt = u.Id FROM @rows r
JOIN [Authorisation].dbo.Users u ON u.Email COLLATE DATABASE_DEFAULT = r.ExecutorEmail COLLATE DATABASE_DEFAULT
                                AND u.OrganisationId = @AuthOrganisationId;

-- The substep (NetworkId 4) under the step (NetworkId 3) of the job copy that takes the material.
UPDATE r SET SubstepNodeId = ss.Id FROM @rows r
JOIN @jobNodes j ON j.Job = r.SubJob AND j.Team = r.SubTeam
JOIN dbo.Nodes sn ON sn.NetworkId = 3 AND sn.ParentNodeId = j.NodeId AND sn.HorizontalIndex = r.StepIndex
                 AND sn.OrganisationId = @OrganisationId
JOIN dbo.Nodes ss ON ss.NetworkId = 4 AND ss.ParentNodeId = sn.Id AND ss.HorizontalIndex = r.SubIndex
                 AND ss.OrganisationId = @OrganisationId;

-- The inventory material type and subtype.
UPDATE r SET TypeId = t.Id, TypeGuid = t.Guid FROM @rows r
JOIN [Inventory].dbo.InventoryItemTypes t ON t.Name COLLATE DATABASE_DEFAULT = r.TypeName COLLATE DATABASE_DEFAULT
                                         AND t.OrganisationId = @InvOrganisationId AND t.InventoryClassId = 2;
UPDATE r SET SubTypeId = s.Id, SubTypeGuid = s.Guid FROM @rows r
JOIN [Inventory].dbo.InventoryItemSubTypes s ON s.InventoryItemTypeId = r.TypeId
                                            AND s.Name COLLATE DATABASE_DEFAULT = r.SubTypeName COLLATE DATABASE_DEFAULT
WHERE r.SubTypeName IS NOT NULL;

-- AssignmentId, MaterialTypeId and MaterialSubTypeId take a Guid or an Id, whichever their columns are.
DECLARE @isGuid TABLE (Col sysname, IsGuid bit);
SELECT c.name, CASE WHEN t.name = 'uniqueidentifier' THEN 1 ELSE 0 END
FROM sys.columns c JOIN sys.types t ON t.user_type_id = c.user_type_id
WHERE (c.object_id = OBJECT_ID('dbo.ExecutionMaterials') AND c.name IN ('AssignmentId', 'MaterialTypeId', 'MaterialSubTypeId'))
   OR (c.object_id = OBJECT_ID('dbo.Assignments') AND c.name = 'ExecutorId');
DECLARE @byGuid  bit = (SELECT IsGuid FROM @isGuid WHERE Col = 'ExecutorId');
DECLARE @asGuid  bit = (SELECT IsGuid FROM @isGuid WHERE Col = 'AssignmentId');
DECLARE @tyGuid  bit = (SELECT IsGuid FROM @isGuid WHERE Col = 'MaterialTypeId');
DECLARE @subGuid bit = (SELECT IsGuid FROM @isGuid WHERE Col = 'MaterialSubTypeId');
IF OBJECT_ID('tempdb..#material_rows') IS NOT NULL DROP TABLE #material_rows;
SELECT * INTO #material_rows FROM @rows;
ALTER TABLE #material_rows ADD AssignmentKey nvarchar(50) NULL;
DECLARE @find nvarchar(max) = N'
UPDATE r SET AssignmentKey = CONVERT(nvarchar(50), ' + CASE WHEN @asGuid = 1 THEN N'a.Guid' ELSE N'a.Id' END + N')
FROM #material_rows r JOIN dbo.Assignments a ON a.SpecId = r.SpecId AND a.NodeId = r.NodeId
 AND a.ExecutorId = ' + CASE WHEN @byGuid = 1 THEN N'r.ExecutorGuid' ELSE N'r.ExecutorInt' END + N';';
EXEC sp_executesql @find;

IF EXISTS (SELECT 1 FROM #material_rows WHERE AssignmentKey IS NULL OR SubstepNodeId IS NULL OR TypeId IS NULL
                                  OR (SubTypeName IS NOT NULL AND SubTypeId IS NULL))
BEGIN
    SELECT DISTINCT TOP (50) SpecName, JobName, TeamName, ExecutorEmail, SubJob, SubTeam, StepIndex, SubIndex, TypeName, SubTypeName,
           CASE WHEN SpecId IS NULL THEN 'spec not found (run the test cases)'
                WHEN NodeId IS NULL OR ExecutorGuid IS NULL OR AssignmentKey IS NULL THEN 'assignment not found (run assignments.sql)'
                WHEN SubstepNodeId IS NULL THEN 'substep not found (run substeps.sql)'
                WHEN TypeId IS NULL THEN 'material type not found (run inventory/item_types.sql)'
                ELSE 'material subtype not found (run inventory/item_types.sql)' END AS Problem
    FROM #material_rows WHERE AssignmentKey IS NULL OR SubstepNodeId IS NULL OR TypeId IS NULL
                  OR (SubTypeName IS NOT NULL AND SubTypeId IS NULL);
    DROP TABLE #material_rows;
    RAISERROR('Some assignments, substeps or material types could not be found (see grid): nothing written.', 16, 1);
    RETURN;
END

BEGIN TRANSACTION;

DECLARE @removed int = 0, @added int = 0;
IF @Reset = 1
BEGIN
    DECLARE @clear nvarchar(max) = N'
    DELETE m FROM dbo.ExecutionMaterials m JOIN dbo.Assignments a ON m.AssignmentId = ' +
        CASE WHEN @asGuid = 1 THEN N'a.Guid' ELSE N'a.Id' END + N'
    WHERE a.SpecId IN (SELECT DISTINCT SpecId FROM #material_rows);
    SELECT @removed = @@ROWCOUNT;';
    EXEC sp_executesql @clear, N'@removed int OUTPUT', @removed OUTPUT;
END

DECLARE @insert nvarchar(max) = N'
                                    ModificationDate, CreatedBy, ModifiedBy)
SELECT r.AssignmentKey, r.SubstepNodeId, ' + CASE WHEN @tyGuid = 1 THEN N'r.TypeGuid' ELSE N'r.TypeId' END + N', '
    + CASE WHEN @subGuid = 1 THEN N'r.SubTypeGuid' ELSE N'r.SubTypeId' END + N', r.Value, r.CreationDate, NULL, @CreatedBy, NULL
FROM #material_rows r;
SELECT @added = @@ROWCOUNT;';
EXEC sp_executesql @insert, N'@CreatedBy uniqueidentifier, @added int OUTPUT', @CreatedBy, @added OUTPUT;

SELECT @removed AS MaterialUsesRemoved, @added AS MaterialUsesAdded;
SELECT SpecName, TypeName, COUNT(*) AS Uses, SUM(Value) AS Total FROM #material_rows GROUP BY SpecName, TypeName ORDER BY SpecName, COUNT(*) DESC;
DROP TABLE #material_rows;

IF @Commit = 1 BEGIN COMMIT TRANSACTION;   PRINT 'Committed.'; END
ELSE           BEGIN ROLLBACK TRANSACTION; PRINT 'Dry run: rolled back.'; END
